def coin_change_ways(coins: list[int], amount: int) -> int:
    if amount == 0:
        return 1

    combinations_result = 0
    for coin_combinations in combinations(coins, amount):
        coin_values = sum(coin for coin in coin_combinations)
        if coin_values <= amount:
            combinations_result += coin_values // amount * coin_change_ways(coin_combinations, amount - coin_values % amount)

    return combinations_result

