def count_islands(grid: list[str]) -> int:
    island_count = empty_count = 0

    for row in grid:
        for cell in row:
            if cell == '1':
                island_count += 1
            elif cell == '0':
                empty_count += 1

    for direction in itertools.product([-1, 0, 1], [-1, 0, 1]):
        x, y = direction
        if 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x+x][y+y] == '0':
            empty_count += 1

    return island_count + empty_count

from collections import deque

def shortest_path_len(n: int, edges: list[list[int]], src: int, dst: int) -> int:
    # Create a graph using a dictionary where keys are nodes and values are lists of adjacent nodes
    graph = {i: [] for i in range(n)}
    for edge in edges:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])

    # Create a queue to store nodes in a breadth-first search order
    queue = deque()

    # Initialize the distance of the source node to 0
    distances = {i: float('inf') for i in range(n)}
    distances[src] = 0

    # Add the source node to the queue and update its distance
    queue.append(src)
    distances[src] = 0

    while queue:
        node = queue.popleft()
        for neighbor, weight in graph[node]:
            new_distance = distances[node] + weight

            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                queue.append(neighbor)

    if distances[dst] == float('inf'):
        return -1

    return distances[dst]

def shortest_path_len(n: int, edges: list[list[int]], src: int, dst: int) -> int:
    # Create a dictionary to store the shortest path lengths from the source node
    dist = {src: 0}

    # Iterate through the graph and update the shortest path lengths
    for node in edges:
        if node[0] != src:
            dist[node[1]] = min(dist[node[1]], dist[node[0]] + 1)

    # Check if the destination node is unreachable or the source node is the destination
    if dst in dist and dist[dst] == n:
        return -1
    elif src == dst:
        return 0

    return dist[dst]

def can_finish(n: int, prereqs: list[list[int]]):
    graph = {}
    for i, j in prereqs:
        graph[i].append(j)

    visited = set()
    queue = [0]

    while queue:
        curr_node = queue.pop(0)
        visited.add(curr_node)

        for next_node in graph[curr_node]:
            if next_node not in visited:
                queue.append(next_node)
                visited.add(next_node)

    return len(visited) == n

def can_finish(n: int, prereqs: list[list[int]]) -> bool:
    if n == 0:
        return True
    if n == 1:
        return True

    visited = set()
    for course_index in range(n):
        if course_index in visited:
            return False
        visited.add(course_index)

        for prerequisite in prereqs[course_index]:
            if prerequisite not in visited:
                return False

    return True

