    if n == 0:
        return 0

    # Initialize the minimum number of jumps and a helper function to check if a jump is possible
    jumps = n
    is_jump_possible = lambda i: i < n - 1 and nums[i] > nums[i + 1]

    # Iterate from the first element to the second-to-last element
    for i in range(1, n - 1):
        # If a jump is possible, decrement the number of jumps
        if is_jump_possible(i):
            jumps -= 1

    # If the list is empty, return the number of jumps
    if jumps == 0:
        return jumps

    # If the last element is smaller than the previous one, return the number of jumps
    if nums[-1] <= nums[n - 1]:
        return jumps

    # Otherwise, decrement the number of jumps and continue the loop
    jumps -= 1

def min_jumps(nums):
